const $ = (q, root = document) => root.querySelector(q);
const $$ = (q, root = document) => [...root.querySelectorAll(q)];
const e = (value) => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons = {
 fish:'<path d="M18 8c-4-5-10-4-14 4 4 8 10 9 14 4l5 4V4z"/><circle cx="9" cy="11" r=".8" fill="currentColor" stroke="none"/>',
 grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
 articles:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>',
 chart:'<path d="M4 3v17h17M8 15l4-5 4 2 5-7"/>',
 users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m3 10v-3a6 6 0 0 0-2-4"/>',
 bot:'<rect x="4" y="7" width="16" height="13" rx="3"/><path d="M12 3v4M1 12v4m22-4v4M8 16h8"/><circle cx="8" cy="11" r=".6" fill="currentColor"/><circle cx="16" cy="11" r=".6" fill="currentColor"/>',
 settings:'<path d="m9 3-1 3-3 1-2 3 2 2v3l-1 2 3 3 3-1 2 2 3-1 1-3 3-1 2-3-2-2V9l1-2-3-3-3 1-2-2z"/><circle cx="12" cy="12" r="3"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',chevron:'<path d="m9 5 7 7-7 7"/>',
 search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',
 logout:'<path d="M9 4H4v16h5m5-12 4 4-4 4m-6-4h14"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',
 calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',check:'<path d="m5 12 4 4L20 5"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>',
 edit:'<path d="m15 4 5 5M4 20l5-1L21 7a3.5 3.5 0 0 0-5-5L4 14z"/>',link:'<path d="m9 15 6-6m-8 3-3 3a4 4 0 0 0 6 6l4-4m-4-10 4-4a4 4 0 0 1 6 6l-3 3"/>',
 menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',refresh:'<path d="M20 7a8 8 0 1 0 0 10M20 3v5h-5"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',
 key:'<circle cx="8" cy="8" r="5"/><path d="m12 12 9 9m-3-3 3-3m-6 0 3-3"/>',filter:'<path d="M3 5h18l-7 8v6l-4 2v-8z"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z"/>'
};
const icon = (name,size=17) => `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name] || icons.articles}</svg>`;
const platforms = {toutiao:'今日头条',zhihu:'知乎',wechat:'微信公众号',other:'其他平台'};
const modeLabels = {manual:'人工',automatic:'自动化',mixed:'人工＋自动化',unknown:'未记录'};
const kindLabels = {latest:'最新数据',d1:'第 1 天观察',d3:'第 3 天观察',d7:'第 7 天观察'};
const metrics = {reads:'阅读',impressions:'展现',likes:'点赞',comments:'评论',favorites:'收藏',shares:'分享',approvals:'赞同',reading_users:'阅读人数'};
const nav = [{id:'dashboard',label:'驾驶舱',icon:'grid',sub:'账号矩阵总览'},{id:'articles',label:'发布统计',icon:'articles',sub:'每一次发布，都有记录'},{id:'reviews',label:'复盘',icon:'chart',sub:'让数据成为下一篇的线索'},{id:'accounts',label:'账号管理',icon:'users',sub:'你的内容账号矩阵'},{id:'keys',label:'AI 接入',icon:'bot',sub:'让 AI 安全地与你协作'},{id:'settings',label:'设置',icon:'settings',sub:'安全与操作记录'}];
const state = {me:null,savedViews:[],accounts:[],page:'dashboard',account:'',reviewTab:'observations',articles:[],columns:new Set(['account','published','mode','duration','reads']),filters:{q:'',mode:'',from:'',to:'',sort:'published_at',order:'desc',group:''},trendMetric:'reads'};
let renderVersion=0, lastFocus=null, searchTimer=null;
const storage = {get(key){try{return localStorage.getItem(key)}catch{return null}},set(key,value){try{localStorage.setItem(key,value)}catch{}}};
const num = value => value === null || value === undefined || value === '' ? '—' : new Intl.NumberFormat('zh-CN',{maximumFractionDigits:1}).format(Number(value));
const compact = value => value == null ? '—' : Number(value)>=10000 ? `${num(Number(value)/10000)}万` : num(value);
const bjtDate = (value = new Date()) => new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value));
const time = (value,short=false) => {if(!value)return '未记录';const d=new Date(value);if(Number.isNaN(d.getTime()))return '未记录';return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',...(short?{}:{year:'numeric'}),hour:'2-digit',minute:'2-digit',hour12:false}).format(d)};
const duration = seconds => {if(seconds==null)return '未记录';const n=Number(seconds);if(n<60)return `${Math.round(n)} 秒`;if(n<3600)return `${Math.round(n/60)} 分钟`;const h=Math.floor(n/3600),m=Math.round((n%3600)/60);return m===60?`${h+1} 小时`:`${h} 小时${m?` ${m} 分钟`:''}`};
const localDateTime = value => {if(!value)return '';const d=new Date(value);if(Number.isNaN(d.getTime()))return '';return new Date(d.getTime()+8*3600000).toISOString().slice(0,16)};
const iso = value => value ? new Date(`${value}:00+08:00`).toISOString() : null;
const metricData = item => {const raw=item?.metrics ?? item?.metrics_json ?? {};if(typeof raw==='string'){try{return JSON.parse(raw)}catch{return {}}}return raw||{}};
const accountLabel = account => `${platforms[account.platform] || account.platform} · ${account.name}`;
const accountName = id => {const a=state.accounts.find(a=>a.id===id);return a?accountLabel(a):'未找到账号'};
const platformLogo = p => `<span class="platform-logo platform-${e(['toutiao','zhihu','wechat'].includes(p)?p:'other')}">${e({toutiao:'头',zhihu:'知',wechat:'微'}[p] || '文')}</span>`;
const selectedQuery = () => state.account?`account_id=${encodeURIComponent(state.account)}`:'';
const rowsForAccount = rows => state.account?rows.filter(a=>a.account_id===state.account):rows;

async function api(path,options={}) {
 const opts={credentials:'same-origin',...options,headers:{Accept:'application/json',...(options.headers || {})}};
 if(opts.body!==undefined){opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(opts.body)}
 if(opts.method && !['GET','HEAD'].includes(opts.method) && state.me?.csrfToken)opts.headers['X-CSRF-Token']=state.me.csrfToken;
 let response;
 try {response=await fetch(`/api/v1${path}`,opts)} catch {throw new Error('暂时无法连接网站，请检查网络后重试。')}
 let payload;try{payload=await response.json()}catch{throw new Error('服务暂时不可用，请稍后重试。')}
 if(!response.ok){if(response.status===401 && path!=='/auth/login'){state.me=null;closeModal();renderLogin()};const err=new Error(payload.error?.message || (response.status===409?'记录已更新，请刷新后重新编辑。':'操作失败，请稍后重试。'));err.status=response.status;err.code=payload.error?.code;throw err}
 return payload.data;
}
function toast(message,error=false){const node=document.createElement('div');node.className=`toast${error?' error':''}`;node.setAttribute('role',error?'alert':'status');node.textContent=message;$('#toasts').append(node);while($('#toasts').children.length>3)$('#toasts').firstElementChild.remove();setTimeout(()=>node.remove(),error?8000:4500)}
function empty(title,description='',action=''){return `<div class="empty"><span class="empty-icon">${icon('articles',22)}</span><h3>${e(title)}</h3>${description?`<p>${e(description)}</p>`:''}${action}</div>`}
function badgeMode(mode){return `<span class="badge ${mode==='automatic'?'green':mode==='mixed'?'blue':''}">${e(modeLabels[mode]||modeLabels.unknown)}</span>`}
function headerActions(){if(state.page==='articles')return `<a class="btn" href="/api/v1/export" download>${icon('download')}<span class="hide-mobile">导出</span></a><button class="btn primary" data-action="new-article">${icon('plus')}记录发布</button>`;if(state.page==='reviews')return `<button class="btn primary" data-action="new-review">${icon('plus')}录入数据</button>`;if(state.page==='accounts')return `<button class="btn primary" data-action="new-account">${icon('plus')}添加账号</button>`;if(state.page==='keys')return `<button class="btn primary" data-action="new-key">${icon('plus')}创建凭证</button>`;return `<button class="btn" data-action="refresh">${icon('refresh')}<span class="hide-mobile">刷新</span></button>`}
function accountOptions(selected='',all=true,activeOnly=false){return `${all?'<option value="">全部账号</option>':''}${state.accounts.filter(a=>!activeOnly||a.active||a.id===selected).map(a=>`<option value="${e(a.id)}" ${a.id===selected?'selected':''}>${e(accountLabel(a))}${a.active?'':'（已停用）'}</option>`).join('')}`}
function renderShell(){const page=nav.find(p=>p.id===state.page)||nav[0];$('#app').innerHTML=`<div class="shell"><aside class="sidebar" aria-label="主要导航"><a href="?page=dashboard" class="brand" data-nav="dashboard"><span class="brand-mark">${icon('fish',27)}</span><span><span class="brand-title">好多鱼图文</span><span class="brand-sub">CONTENT WORKSPACE</span></span></a><div class="nav-label">工作空间</div><nav class="nav-list">${nav.map((n,i)=>`${i===3?'<div class="nav-spacer"></div><div class="nav-label">管理</div>':''}<a href="?page=${n.id}" data-nav="${n.id}" class="nav-item ${n.id===state.page?'active':''}" ${n.id===state.page?'aria-current="page"':''}>${icon(n.icon,18)}${n.label}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="private-badge"><strong>${icon('lock',13)}私有工作空间</strong><p>你的数据，只与你和授权 AI 共享。</p></div><div class="user-row"><span class="avatar">${e((state.me.username||'我').slice(0,1).toUpperCase())}</span><span><div class="user-name">${e(state.me.username)}</div><div class="user-role">空间管理员</div></span><button class="logout" data-action="logout" title="退出登录" aria-label="退出登录">${icon('logout',16)}</button></div></div></aside><div class="workspace"><header class="topbar"><div class="crumb"><button class="mobile-menu icon-button" data-action="menu" aria-label="打开导航" aria-expanded="false">${icon('menu',20)}</button><span class="crumb-home">工作空间</span><span class="crumb-sep">/</span><strong>${e(page.label)}</strong></div><div class="top-actions"><span class="day-label">${e(new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'long',day:'numeric',weekday:'long'}).format(new Date()))}</span><label class="account-select">${icon('users',14)}<span class="sr-only">切换运营账号</span><select id="global-account" aria-label="切换运营账号">${accountOptions(state.account)}</select></label></div></header><main id="main" class="content" tabindex="-1"><div class="page-head"><div><div class="eyebrow">${e({dashboard:'YOUR CONTENT, AT A GLANCE',articles:'PUBLISHING LIBRARY',reviews:'LEARN FROM EVERY STORY',accounts:'YOUR ACCOUNT MATRIX',keys:'CONNECTED INTELLIGENCE',settings:'WORKSPACE SETTINGS'}[state.page])}</div><h1>${e(page.label)}</h1><p>${e(page.sub)}</p></div><div class="head-actions">${headerActions()}</div></div><div id="page-content"><div class="page-loading"><span class="spinner"></span><p>正在读取数据…</p></div></div><p class="footer-note">好多鱼图文 · 让每一篇内容都有迹可循　<span>所有时间均为北京时间</span></p></main></div></div>`;renderPage()}
function updateRoute(){const u=new URL(location.href);u.searchParams.set('page',state.page);if(state.account)u.searchParams.set('account',state.account);else u.searchParams.delete('account');history.replaceState({},'',u);storage.set('haoduoyu.account',state.account)}
function navigate(page){if(!nav.some(n=>n.id===page))return;state.page=page;updateRoute();closeModal();renderShell();window.scrollTo({top:0,behavior:'instant'})}
async function renderPage(){const version=++renderVersion;try{let html='';switch(state.page){case 'dashboard':html=renderDashboard(await api(`/dashboard?${selectedQuery()}`));break;case 'articles':html=await renderArticles();break;case 'reviews':html=await renderReviews();break;case 'accounts':html=renderAccounts();break;case 'keys':html=renderKeys(await api('/api-keys'));break;case 'settings':html=renderSettings(await api('/audit'));break}if(version===renderVersion&&state.me&&$('#page-content'))$('#page-content').innerHTML=html}catch(err){if(version===renderVersion&&state.me&&$('#page-content'))$('#page-content').innerHTML=`<div class="card error-panel"><span class="empty-icon">${icon('info',23)}</span><h3>暂时未能读取数据</h3><p>${e(err.message)}</p><button class="btn" data-action="refresh">${icon('refresh')}重新加载</button></div>`}}
function renderDashboard(data){const accounts=[...(data.accounts||[])].sort((a,b)=>state.accounts.findIndex(x=>x.id===a.id)-state.accounts.findIndex(x=>x.id===b.id)),totals=data.totals||{},windowData=data.window||{};state.dashboard=data;const range=windowData.from&&windowData.to?`${windowData.from.slice(5).replace('-','.')} — ${windowData.to.slice(5).replace('-','.')}`:'最近 3 个自然日';return `<section class="welcome"><div><div class="eyebrow">每一份积累，都在这里</div><h2>看见内容的表现，找到下一步方向。</h2><p>按账号查看最近三天新增的效果，包含历史文章的持续表现。</p></div><div class="welcome-side"><div class="period-label">${icon('calendar',14)}${e(range)}<span class="status-dot"></span>今日未完结</div></div></section><div class="section-heading"><div class="heading-left"><h2>账号表现</h2><span class="badge">${accounts.length} 个账号</span></div><small>最近 3 个自然日 · ${e(range)}</small></div><section class="account-grid">${accounts.length?accounts.map(renderAccountCard).join(''):empty('还没有运营账号','添加一个账号，开始积累内容数据。','<button class="btn primary" data-action="new-account">添加账号</button>')}</section><div class="main-grid"><section class="card panel"><div class="chart-header"><div><h2>近期效果趋势</h2><p>每日新增数据 · 缺失记录保留空白 · 今天尚未结束</p></div><label><span class="sr-only">趋势指标</span><select id="trend-metric" class="input">${Object.entries(metrics).map(([key,label])=>`<option value="${key}" ${state.trendMetric===key?'selected':''}>${label}</option>`).join('')}</select></label></div>${renderTrend(data)}</section><section class="card panel"><div class="section-heading"><div class="heading-left"><h2>等待复盘</h2><span class="badge amber">${num((data.due_reviews||[]).length)}</span></div><button class="btn text" data-nav="reviews">全部 ${icon('arrow',13)}</button></div>${(data.due_reviews||[]).length?`<div class="review-list">${data.due_reviews.slice(0,5).map(r=>`<div class="review-item"><span class="review-dot"></span><div><button class="article-link review-item-title" data-action="article-detail" data-id="${e(r.id)}">${e(r.title)}</button><div class="review-item-meta">${e(r.account_name||accountName(r.account_id))} · ${e(kindLabels[r.due_kind]||r.due_kind)}<br>目标时间 ${e(time(r.due_at))}</div></div><button class="btn small" data-action="review-article" data-id="${e(r.id)}" data-kind="${e(r.due_kind)}">补录</button></div>`).join('')}</div>`:empty('复盘清单是清爽的','发布文章后，到期的 1／3／7 天观察任务会出现在这里。')}</section></div><div class="section-heading"><h2>发布效率</h2><small>当前筛选下全部已发布文章</small></div><section class="efficiency">${efficiencyCard('articles','已发布文章',`${num(totals.article_count??0)} 篇`)}${efficiencyCard('bot','自动化生产占比',Number(totals.article_count)>0?`${Math.round(Number(totals.automatic_count||0)/totals.article_count*100)}%`:'—')}${efficiencyCard('clock','全流程耗时中位数',duration(totals.median_duration_seconds))}${efficiencyCard('info','生产方式待补充',`${num(totals.unknown_mode_count??0)} 篇`)}</section><section class="card"><div class="panel section-heading"><div><h2>文章表现</h2><p class="cell-sub">按最新累计阅读展示 · 跨平台指标口径各自保留</p></div><button class="btn text" data-nav="articles">发布记录 ${icon('arrow',13)}</button></div>${(data.top_articles||[]).length?articleTable(data.top_articles,{compact:true}):empty('第一篇内容，从这里开始','记录已发布文章，再由你或 Grok 补充表现数据。','<button class="btn" data-action="new-article">'+icon('plus',14)+'记录一篇文章</button>')}</section>`}
function efficiencyCard(i,label,value){return `<div class="efficiency-card"><span class="efficiency-icon">${icon(i,16)}</span><div><div class="efficiency-label">${e(label)}</div><div class="efficiency-value">${e(value)}</div></div></div>`}
function renderAccountCard(a){const m=a.period_metrics||{},coverage=a.coverage||{};const partial=Number(coverage.metric_days?.reads??coverage.days)<3;const incomplete=Number(coverage.days)<3||Object.values(coverage.metric_days||{}).some(n=>Number(n)<3)||['articles','mixed','missing'].includes(coverage.source);return `<article class="card account-card"><div class="account-card-top">${platformLogo(a.platform)}<div><div class="account-card-title">${e(a.name)}</div><div class="account-card-sub">${e(platforms[a.platform]||a.platform)} · ${num(a.article_count??0)} 篇已发布</div></div><button class="icon-button" data-action="select-account" data-id="${e(a.id)}" title="查看此账号" aria-label="查看${e(a.name)}的全部数据">${icon('chevron',15)}</button></div><div class="metric-label">三天新增阅读${partial&&m.reads!=null?'（已采集部分）':''}</div><div class="big-value">${compact(m.reads)}</div><div class="metric-context">${m.reads==null?'尚未取得阅读周期数据':`${e(coverage.label||`${coverage.days??0} 天已有数据`)} · 今日未完结`}</div><dl class="metric-row"><div><dt>展现</dt><dd>${compact(m.impressions)}</dd></div><div><dt>${a.platform==='zhihu'?'赞同':'点赞'}</dt><dd>${compact(a.platform==='zhihu'?m.approvals:m.likes)}</dd></div><div><dt>评论</dt><dd>${compact(m.comments)}</dd></div></dl><div class="account-foot"><span class="badge ${incomplete?'amber':'green'}">${e(coverage.label || (coverage.source==='missing'?'数据待补充':'按已采集记录展示'))}</span><span>${a.last_updated?`更新 ${e(time(a.last_updated,true))}`:'尚无数据'}</span></div></article>`}
function renderTrend(data){const dates=data.trend||[],accounts=data.accounts||[],key=state.trendMetric,colors=['#307e68','#91a8c4','#cbb576','#a889b1','#b87f70'];const all=dates.flatMap(d=>(d.accounts||[]).map(a=>a.metrics?.[key])).filter(v=>v!=null);if(!all.length)return `<div class="chart-blank">${icon('chart',34)}<h3>还没有${e(metrics[key])}趋势</h3><p>录入每日周期数据后，趋势会自然呈现。累计快照不会自动当作每日新增。</p></div>`;const max=Math.max(...all.map(Number),1),w=620,h=200,left=46,right=20,top=12,bottom=32,plotW=w-left-right,plotH=h-top-bottom;const x=i=>left+(dates.length>1?i*plotW/(dates.length-1):plotW/2),y=v=>top+plotH-(Number(v)/max)*plotH;return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="最近三天各账号${e(metrics[key])}趋势，缺失数据不连线"><g>${[0,.5,1].map(t=>`<line x1="${left}" x2="${w-right}" y1="${top+t*plotH}" y2="${top+t*plotH}" stroke="#eaf0e4" stroke-dasharray="4 5"/><text x="${left-9}" y="${top+t*plotH+4}" text-anchor="end">${compact(max*(1-t))}</text>`).join('')}</g>${accounts.map((a,i)=>{let prev=null,segments='';const points=dates.map((d,j)=>{const val=(d.accounts||[]).find(p=>p.account_id===a.id)?.metrics?.[key];if(val==null){prev=null;return ''}const point={x:x(j),y:y(val)};if(prev)segments+=`<line x1="${prev.x}" y1="${prev.y}" x2="${point.x}" y2="${point.y}" stroke="${colors[i%colors.length]}" stroke-width="2"/>`;prev=point;return `<circle cx="${point.x}" cy="${point.y}" r="4" fill="${colors[i%colors.length]}" stroke="#fff" stroke-width="2"><title>${e(a.name)} · ${e(d.date)} · ${num(val)}</title></circle>`});return segments+points.join('')}).join('')}${dates.map((d,i)=>`<text x="${x(i)}" y="${h-9}" text-anchor="middle">${e(d.date?.slice(5))}${d.date===bjtDate()?' 今日':''}</text>`).join('')}</svg><div class="chart-legend">${accounts.map((a,i)=>`<span><i class="legend-dot" style="background:${colors[i%colors.length]}"></i>${e(accountLabel(a))}</span>`).join('')}</div><details class="cell-sub"><summary>查看每日明细</summary><div class="table-scroll"><table class="data-table"><thead><tr><th>日期</th>${accounts.map(a=>`<th>${e(a.name)}</th>`).join('')}</tr></thead><tbody>${dates.map(d=>`<tr><td>${e(d.date)}</td>${accounts.map(a=>`<td>${num((d.accounts||[]).find(r=>r.account_id===a.id)?.metrics?.[key])}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`}
async function renderArticles(){const f=state.filters,params=new URLSearchParams();if(state.account)params.set('account_id',state.account);for(const key of ['q','mode','from','to','sort','order'])if(f[key])params.set(key,f[key]);state.articles=await api(`/articles?${params}`);return `<section class="card"><div class="view-bar"><label><span class="sr-only">已保存的表格视图</span><select class="input" id="saved-view"><option value="">选择常用视图</option>${state.savedViews.map(v=>`<option value="${e(v.id)}">${e(v.name)}</option>`).join('')}</select></label><button class="btn small" data-action="save-view">${icon('plus',13)}保存当前视图</button><span class="cell-sub">视图保存在此浏览器</span></div><form id="article-filters" class="filters"><label class="search">${icon('search',15)}<input class="input" name="q" value="${e(f.q)}" placeholder="搜索文章标题、链接…" aria-label="搜索文章"></label><select name="mode" class="input" aria-label="按生产方式筛选"><option value="">全部生产方式</option>${Object.entries(modeLabels).map(([key,label])=>`<option value="${key}" ${f.mode===key?'selected':''}>${e(label)}</option>`).join('')}</select><select name="sort" class="input" aria-label="排序方式"><option value="published_at" ${f.sort==='published_at'?'selected':''}>按发布时间</option><option value="reads" ${f.sort==='reads'?'selected':''}>按累计阅读</option><option value="duration" ${f.sort==='duration'?'selected':''}>按全流程耗时</option></select><select name="order" class="input" aria-label="排序方向"><option value="desc" ${f.order==='desc'?'selected':''}>从高到低／从新到旧</option><option value="asc" ${f.order==='asc'?'selected':''}>从低到高／从旧到新</option></select><select name="group" class="input" aria-label="分组方式"><option value="">不分组</option><option value="account" ${f.group==='account'?'selected':''}>按账号分组</option><option value="mode" ${f.group==='mode'?'selected':''}>按生产方式分组</option></select><input type="date" class="input" name="from" value="${e(f.from)}" aria-label="发布起始日期"><span class="date-sep">至</span><input type="date" class="input" name="to" value="${e(f.to)}" aria-label="发布结束日期"><button type="button" class="btn text" data-action="reset-filters">重置</button></form><details><summary class="btn text" style="margin:8px 15px">${icon('filter',13)}显示字段</summary><div class="column-controls">${Object.entries({account:'所属账号',published:'发布时间',mode:'生产方式',duration:'全流程耗时',reads:'累计阅读'}).map(([key,label])=>`<label class="check-option"><input type="checkbox" data-column="${key}" ${state.columns.has(key)?'checked':''}>${label}</label>`).join('')}</div></details><div id="article-table">${state.articles.length?articleTable(state.articles):empty('没有符合条件的文章','这里只记录成功发布的文章。你和授权 AI 都可以填写。','<button class="btn" data-action="new-article">'+icon('plus',14)+'记录发布</button>')}</div><div class="table-footer">共 ${state.articles.length} 篇 · 点击标题查看详情 · 空白数据不会按 0 计算</div></section>`}
function articleTable(rows,{compact:mini=false}={}){const c=mini?new Set(['account','reads','published']):state.columns;const head=`<tr><th>文章</th>${c.has('account')?'<th>所属账号</th>':''}${c.has('published')?'<th>发布时间</th>':''}${c.has('mode')?'<th>生产方式</th>':''}${c.has('duration')?'<th>全流程耗时</th>':''}${c.has('reads')?'<th>累计阅读</th>':''}<th></th></tr>`;let last=null;const bodies=rows.map(a=>{let group='';if(!mini&&state.filters.group){const key=state.filters.group==='account'?a.account_id:a.production_mode;const label=state.filters.group==='account'?accountName(a.account_id):modeLabels[a.production_mode]||'未记录';if(last!==key){group=`<tr class="group-row"><td colspan="${c.size+2}">${e(label)}</td></tr>`;last=key}}return `${group}<tr><td class="title-cell"><button class="article-link" data-action="article-detail" data-id="${e(a.id)}">${e(a.title)}</button>${mini?'':`<div class="cell-sub">${e(a.summary?String(a.summary).slice(0,75):'已成功发布')}</div>`}</td>${c.has('account')?`<td><div>${e(a.account_name||state.accounts.find(x=>x.id===a.account_id)?.name||'—')}</div><div class="cell-sub">${e(platforms[a.platform]||a.platform||'')}</div></td>`:''}${c.has('published')?`<td class="number">${e(time(a.published_at))}</td>`:''}${c.has('mode')?`<td>${badgeMode(a.production_mode)}</td>`:''}${c.has('duration')?`<td>${e(duration(a.duration_seconds))}</td>`:''}${c.has('reads')?`<td class="number">${num(a.latest_metrics?.reads)}${a.latest_as_of?`<div class="cell-sub">截至 ${e(time(a.latest_as_of,true))}</div>`:''}</td>`:''}<td><button class="icon-button" data-action="edit-article" data-id="${e(a.id)}" title="编辑文章" aria-label="编辑${e(a.title)}">${icon('edit',15)}</button></td></tr>`});if(!mini&&state.filters.group){const key=state.filters.group==='account'?'account_id':'production_mode';const sorted=[...rows].sort((a,b)=>String(a[key]??'').localeCompare(String(b[key]??'')));if(sorted.some((a,i)=>a.id!==rows[i]?.id))return articleTable(sorted,{compact:mini})}return `<div class="table-scroll"><table class="data-table"><thead>${head}</thead><tbody>${bodies.join('')}</tbody></table></div>`}
async function renderReviews(){const [articles,records]=await Promise.all([api(`/articles?${selectedQuery()}`),api(`/${state.reviewTab==='observations'?'observations':'daily-metrics'}?${selectedQuery()}`)]);state.articles=articles;state.reviewRecords=records;return `<div class="info-line">${icon('info',15)}<span>${state.reviewTab==='observations'?'累计快照记录文章当时的总表现。1／3／7 天为观察目标，网站同时保留实际数据时间。':'每日周期数据记录当天实际新增的效果，用于首页最近三天统计。账号总体和文章明细分开保存，同一天优先采用账号总体。'}</span></div><div class="tabs" role="tablist" aria-label="复盘数据类型"><button class="tab ${state.reviewTab==='observations'?'active':''}" role="tab" aria-selected="${state.reviewTab==='observations'}" data-action="review-tab" data-tab="observations">文章累计快照</button><button class="tab ${state.reviewTab==='daily'?'active':''}" role="tab" aria-selected="${state.reviewTab==='daily'}" data-action="review-tab" data-tab="daily">每日新增数据</button></div><section class="card">${records.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>${state.reviewTab==='observations'?'文章／观察节点':'日期／统计范围'}</th><th>所属账号</th><th>阅读</th><th>展现</th><th>点赞／赞同</th><th>评论</th><th>${state.reviewTab==='observations'?'数据截至':'来源'}</th><th></th></tr></thead><tbody>${records.map(row=>{const article=articles.find(a=>a.id===row.article_id),m=metricData(row),accountId=row.account_id||article?.account_id;return `<tr><td class="title-cell">${state.reviewTab==='observations'?`<button class="article-link" data-action="article-detail" data-id="${e(row.article_id)}">${e(row.article_title||article?.title||'文章记录')}</button><div class="cell-sub">${e(kindLabels[row.kind]||row.kind)}</div>`:`<strong>${e(row.date)}</strong><div class="cell-sub">${row.article_id?e(row.article_title||article?.title||'文章明细'):'账号总体'}</div>`}</td><td>${e(row.account_name||state.accounts.find(a=>a.id===accountId)?.name||'—')}</td><td>${num(m.reads)}</td><td>${num(m.impressions)}</td><td>${num(m.likes??m.approvals)}</td><td>${num(m.comments)}</td><td>${state.reviewTab==='observations'?`${e(time(row.as_of))}<div class="cell-sub">${e(row.source||'未标注来源')}</div>`:e(row.source||'未标注来源')}</td><td><button class="btn small" data-action="record-detail" data-id="${e(row.id)}">详情</button></td></tr>`}).join('')}</tbody></table></div><div class="table-footer">${records.length} 条记录 · 不同平台指标不合并口径 · 缺项保留为空</div>`:empty('尚未录入这类数据','你可以手动补录，或让授权的 Grok Bot 回填。','<button class="btn" data-action="new-review">'+icon('plus',14)+'录入数据</button>')}</section>`}
function renderAccounts(){const accounts=state.account?state.accounts.filter(a=>a.id===state.account):state.accounts;return `<div class="info-line">${icon('info',15)}<span>运营账号与你的网站登录身份分别管理。停用账号会保留历史文章和数据；授权凭证的账号范围在「AI 接入」中单独设置。</span></div><section class="account-management">${accounts.map(a=>`<article class="card managed-card"><div class="managed-card-top">${platformLogo(a.platform)}<div><h2>${e(a.name)}</h2><div class="cell-sub">${e(platforms[a.platform]||a.platform)}</div></div></div><p>创建于 ${e(time(a.created_at))}</p><div class="managed-card-foot"><span class="badge ${a.active?'green':''}">${a.active?'使用中':'已停用'}</span><button class="btn small" data-action="edit-account" data-id="${e(a.id)}">${icon('edit',13)}管理账号</button></div></article>`).join('')||empty('没有运营账号','添加头条、知乎、公众号或其他平台账号。')}</section>`}
function renderKeys(keys){return `<div class="info-line">${icon('lock',15)}<span>为每个 AI 单独创建凭证，只开放需要的账号和读写权限。凭证只在创建时显示一次，请妥善保管。</span></div><section class="card panel" style="margin-bottom:22px"><div class="section-heading"><h2>让 Grok Bot 连接你的工作空间</h2><a href="/api-docs" class="btn" target="_blank" rel="noopener noreferrer">${icon('link',14)}接入文档</a></div><p class="muted" style="font-size:12px">把接入文档地址提供给 AI，并通过它的安全凭证设置配置授权。AI 可以检索文章、回填发布信息与复盘数据，再读回确认结果。</p></section><section class="card">${keys.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>凭证名称</th><th>账号范围</th><th>权限</th><th>最近使用</th><th>状态</th><th></th></tr></thead><tbody>${keys.map(k=>{let ids=k.account_ids||k.account_ids_json||[],permissions=k.permissions||k.permissions_json||[];if(typeof ids==='string'){try{ids=JSON.parse(ids)}catch{ids=[]}}if(typeof permissions==='string'){try{permissions=JSON.parse(permissions)}catch{permissions=[]}}return `<tr><td>${e(k.name)}<div class="cell-sub">创建 ${e(time(k.created_at))}</div></td><td class="key-scope">${ids.map(id=>e(accountName(id))).join('<br>')||'无账号权限'}</td><td>${permissions.map(p=>`<span class="badge ${p==='write'?'green':''}">${p==='read'?'读取':p==='write'?'写入':e(p)}</span>`).join(' ')}</td><td>${k.last_used_at?e(time(k.last_used_at)):'尚未使用'}</td><td><span class="badge ${k.revoked_at?'':'green'}">${k.revoked_at?'已撤销':'有效'}</span></td><td>${k.revoked_at?'':`<button class="btn small danger" data-action="revoke-key" data-id="${e(k.id)}" data-name="${e(k.name)}">撤销</button>`}</td></tr>`}).join('')}</tbody></table></div>`:empty('还没有连接 AI','创建一个受限凭证，让 Grok 帮你填写数据。','<button class="btn" data-action="new-key">'+icon('plus',14)+'创建凭证</button>')}</section>`}
function auditLabel(action){const routes={'POST /articles':'新增文章','PUT /articles/:id':'修改文章','POST /observations':'追加复盘快照','POST /daily-metrics':'填写每日数据','POST /accounts':'添加账号','PUT /accounts/:id':'修改账号','POST /api-keys':'创建 AI 凭证','DELETE /api-keys/:id':'撤销 AI 凭证','PUT /auth/password':'修改密码','POST /auth/login':'登录网站','POST /auth/logout':'退出登录'};if(routes[action])return routes[action];if(/^PUT \/articles\//.test(action))return '修改文章';if(/^PUT \/accounts\//.test(action))return '修改账号';if(/^DELETE \/api-keys\//.test(action))return '撤销 AI 凭证';return ({'article.create':'新增文章','article.update':'修改文章','observation.create':'追加复盘快照','daily_metrics.upsert':'填写每日数据','account.create':'添加账号','account.update':'修改账号','api_key.create':'创建 AI 凭证','api_key.revoke':'撤销 AI 凭证','auth.password':'修改密码','auth.login':'登录网站','auth.logout':'退出登录'})[action]||action}
function renderSettings(audit){return `<div class="settings-grid"><section class="card panel"><h2>登录与安全</h2><p class="muted" style="font-size:12px;margin-bottom:24px">当前登录：${e(state.me.username)}</p><form id="password-form"><div class="form-field"><label for="current-password">当前密码</label><input class="input" type="password" id="current-password" name="currentPassword" autocomplete="current-password" required></div><div class="form-field" style="margin-top:17px"><label for="new-password">新密码</label><input class="input" type="password" id="new-password" name="newPassword" autocomplete="new-password" minlength="12" required><span class="hint">至少 12 位，建议使用独立的长密码。</span></div><div class="form-field" style="margin-top:17px"><label for="confirm-password">再次输入新密码</label><input class="input" type="password" id="confirm-password" name="confirmPassword" autocomplete="new-password" minlength="12" required></div><p class="form-message" role="alert"></p><div class="form-actions"><button class="btn primary" type="submit">更新密码</button></div></form><div class="detail-section"><h3>数据导出</h3><p class="muted" style="margin-bottom:14px">导出当前工作空间的发布记录，保存一份可查阅的副本。</p><a class="btn" href="/api/v1/export" download>${icon('download',14)}导出发布记录 CSV</a></div></section><section class="card panel"><div class="section-heading"><h2>最近操作</h2><span class="badge">可追溯</span></div><p class="muted" style="font-size:11px;margin-bottom:12px">人工和 AI 的修改都会留下记录。</p><div class="audit-list">${audit.length?audit.map(row=>`<div class="audit-item"><strong>${e(auditLabel(row.action))}</strong><div class="audit-meta">${e(row.actor)} · ${e(time(row.created_at))}${row.entity_id?`<br>记录 ${e(row.entity_id)}`:''}</div></div>`).join(''):empty('还没有操作记录','后续的数据修改会出现在这里。')}</div></section></div>`}

function openModal(title,body,{drawer=false}={}){lastFocus=document.activeElement;$('#overlay').innerHTML=`<div class="modal-backdrop ${drawer?'drawer-backdrop':''}"><section class="modal ${drawer?'drawer':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><h2 id="modal-title">${e(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="关闭">${icon('close',20)}</button></header><div class="modal-body">${body}</div></section></div>`;document.body.style.overflow='hidden';requestAnimationFrame(()=>{const field=$('input:not([type=checkbox]),select,textarea,button',$('#overlay'));field?.focus()})}
function closeModal(){if(!$('#overlay'))return;const wasOpen=!!$('#overlay').firstChild;$('#overlay').innerHTML='';document.body.style.overflow='';if(wasOpen&&lastFocus?.isConnected)lastFocus.focus()}
function field(name,label,type='text',value='',options=''){return `<div class="form-field"><label for="field-${e(name)}">${label}</label><input id="field-${e(name)}" class="input" name="${e(name)}" type="${type}" value="${e(value)}" ${options}></div>`}
function formEnd(label='保存'){return `<p class="form-message" role="alert"></p><div class="form-actions"><button type="button" class="btn" data-action="close-modal">取消</button><button class="btn primary" type="submit">${e(label)}</button></div>`}
async function articleModal(id=''){let a={account_id:state.account,production_mode:'unknown'};if(id)a=await api(`/articles/${encodeURIComponent(id)}`);const activeAccounts=state.accounts.filter(x=>x.active||x.id===a.account_id);if(!activeAccounts.length){toast('请先添加一个启用的运营账号。',true);return}openModal(id?'编辑发布记录':'记录一次成功发布',`<form id="article-form" data-id="${e(id)}" data-version="${e(a.version||'')}"><div class="info-line">${icon('check',14)}<span>仅记录已经成功发布的文章。时间均按北京时间填写。</span></div><div class="form-grid"><div class="form-field full"><label for="field-title">文章标题 <span class="required">*</span></label><input class="input" id="field-title" name="title" value="${e(a.title)}" maxlength="500" required></div><div class="form-field full"><label for="field-account_id">所属运营账号 <span class="required">*</span></label><select class="input" id="field-account_id" name="account_id" required>${accountOptions(a.account_id,false,true)}</select></div><div class="form-field full"><label for="field-url">已发布文章链接 <span class="required">*</span></label><input class="input" id="field-url" name="url" type="url" value="${e(a.url)}" placeholder="https://…" required></div>${field('published_at','实际发布时间 <span class="required">*</span>','datetime-local',localDateTime(a.published_at),'required')}${field('started_at','选题开始时间','datetime-local',localDateTime(a.started_at))}<div class="form-field"><label for="field-production_mode">文章生产方式</label><select class="input" id="field-production_mode" name="production_mode">${Object.entries(modeLabels).map(([key,label])=>`<option value="${key}" ${a.production_mode===key?'selected':''}>${label}</option>`).join('')}</select><span class="hint">录入者由网站记录，与生产方式分别管理。</span></div>${field('platform_article_id','平台文章标识（可选）','text',a.platform_article_id)}<div class="form-field full"><label for="field-summary">文章概况</label><textarea class="input" name="summary" id="field-summary" maxlength="5000" placeholder="这篇文章写了什么…">${e(a.summary)}</textarea></div><div class="form-field full"><label for="field-notes">备注</label><textarea class="input" name="notes" id="field-notes" maxlength="10000">${e(a.notes)}</textarea><span class="hint">全流程耗时由选题开始时间到发布时间计算；不确定的开始时间可以留空。</span></div></div>${formEnd(id?'保存修改':'保存发布记录')}</form>`)}
async function articleDetail(id){const a=await api(`/articles/${encodeURIComponent(id)}`);const observations=a.observations||[];openModal('文章详情',`<span class="badge green">已成功发布</span><h2 class="detail-title">${e(a.title)}</h2><div class="head-actions"><button class="btn small" data-action="edit-article" data-id="${e(a.id)}">${icon('edit',13)}编辑记录</button><button class="btn small primary" data-action="review-article" data-id="${e(a.id)}">${icon('plus',13)}补充复盘</button>${safeURL(a.url)?`<a class="btn small" href="${e(a.url)}" target="_blank" rel="noopener noreferrer">${icon('link',13)}查看原文</a>`:''}</div><dl class="detail-grid"><div><dt>所属账号</dt><dd>${e(accountName(a.account_id))}</dd></div><div><dt>生产方式</dt><dd>${badgeMode(a.production_mode)}</dd></div><div><dt>实际发布时间</dt><dd>${e(time(a.published_at))}</dd></div><div><dt>选题开始时间</dt><dd>${e(time(a.started_at))}</dd></div><div><dt>全流程耗时</dt><dd>${e(duration(a.duration_seconds))}</dd></div><div><dt>录入时间</dt><dd>${e(time(a.created_at))}</dd></div><div><dt>录入者</dt><dd>${e(a.recorded_by?.label||'未记录')}</dd></div><div><dt>最近修改者</dt><dd>${e(a.last_modified_by?.label||'未记录')}${a.last_modified_by?.at?`<div class="cell-sub">${e(time(a.last_modified_by.at))}</div>`:''}</dd></div></dl>${a.summary?`<section class="detail-section"><h3>文章概况</h3><p>${e(a.summary)}</p></section>`:''}${a.notes?`<section class="detail-section"><h3>备注</h3><p>${e(a.notes)}</p></section>`:''}<section class="detail-section"><h3>复盘记录 · ${observations.length} 次</h3><p class="muted" style="font-size:10px">各次观察独立保留；按数据截至时间判断最新记录。</p>${observations.length?observations.map(renderSnapshot).join(''):empty('等待第一次观察','文章发布后，可以由你或 Grok 补充真实数据。')}</section>`,{drawer:true})}
function safeURL(value){try{return ['http:','https:'].includes(new URL(value).protocol)}catch{return false}}
function renderSnapshot(row){const m=metricData(row);return `<article class="snapshot"><div class="snapshot-head"><span class="badge ${row.kind==='latest'?'green':'blue'}">${e(kindLabels[row.kind]||row.kind||'每日数据')}</span><span class="snapshot-time">${e(row.date||time(row.as_of))}</span></div><div class="snapshot-metrics">${Object.entries(metrics).filter(([key])=>m[key]!=null).map(([key,label])=>`<span>${label}<strong>${num(m[key])}</strong></span>`).join('')||'<span>未记录指标</span>'}</div><p class="cell-sub">来源：${e(row.source||'未记录')}${row.collected_at?` · 采集于 ${e(time(row.collected_at))}`:''}</p>${row.note?`<p class="cell-sub">${e(row.note)}</p>`:''}</article>`}
async function reviewModal(articleId='',kind='latest'){const directArticle=Boolean(articleId);const articles=await api('/articles');if(!articleId&&state.account)articleId=articles.find(a=>a.account_id===state.account)?.id||'';state.articles=articles;const daily=state.reviewTab==='daily'&&!directArticle;if(!articles.length&&!daily){openModal('录入复盘数据',empty('先记录一篇已发布文章','累计快照需要关联到已有文章。','<button class="btn primary" data-action="new-article">记录发布</button>'));return}const accountId=state.account||articles.find(a=>a.id===articleId)?.account_id||state.accounts.find(a=>a.active)?.id||'';openModal(daily?'填写每日新增数据':'追加文章累计快照',`<form id="review-form" data-type="${daily?'daily':'observation'}"><div class="info-line">${icon('info',14)}<span>${daily?'填写这一天实际新增的数据，不要填写文章累计值。账号总体与文章明细分开记录。':'填写截至某个时间的累计数据。1／3／7 天为目标节点，实际数据时间请如实填写。'}</span></div><div class="form-grid">${daily?`<div class="form-field full"><label for="review-account">所属账号 <span class="required">*</span></label><select class="input" name="account_id" id="review-account" required>${accountOptions(accountId,false,true)}</select></div><div class="form-field full"><label for="review-article">统计范围</label><select class="input" name="article_id" id="review-article"><option value="">账号总体（推荐）</option>${articles.filter(a=>a.account_id===accountId).map(a=>`<option value="${e(a.id)}">${e(a.title)}</option>`).join('')}</select><span class="hint">同一天优先使用账号总体；仅有文章明细时，首页会标注覆盖范围。</span></div>${field('date','数据所属日期 <span class="required">*</span>','date',bjtDate(),`max="${bjtDate()}" required`)}`:`<div class="form-field full"><label for="review-article">文章 <span class="required">*</span></label><select class="input" name="article_id" id="review-article" required>${articles.map(a=>`<option value="${e(a.id)}" ${a.id===articleId?'selected':''}>${e(a.title)} · ${e(a.account_name||accountName(a.account_id))}</option>`).join('')}</select></div><div class="form-field"><label for="field-kind">观察节点</label><select class="input" id="field-kind" name="kind">${Object.entries(kindLabels).map(([key,label])=>`<option value="${key}" ${key===kind?'selected':''}>${label}</option>`).join('')}</select></div>${field('as_of','数据截至时间 <span class="required">*</span>','datetime-local',localDateTime(new Date()),'required')}${field('collected_at','实际采集时间 <span class="required">*</span>','datetime-local',localDateTime(new Date()),'required')}`}${field('source','数据来源 <span class="required">*</span>','text','','placeholder="例如：头条创作后台 / Grok Bot" required maxlength="200"')}<div class="form-field full"><span class="field-label">${daily?'当天新增指标':'累计指标'}</span><span class="hint">至少填写一个。未知指标留空，确认为零才填 0；不同平台口径分别保留。</span></div>${Object.entries(metrics).map(([key,label])=>field(`metric_${key}`,label,'number','','min="0" step="1" inputmode="numeric" placeholder="未取得"')).join('')}${daily?'':`<div class="form-field full"><label for="field-note">复盘备注</label><textarea class="input" name="note" id="field-note" maxlength="10000" placeholder="数据背景、内容判断、下次改进…"></textarea></div>`}</div>${formEnd(daily?'保存每日数据':'追加快照')}</form>`)}
function accountModal(id=''){const a=state.accounts.find(a=>a.id===id)||{platform:'toutiao',name:'',active:true};openModal(id?'管理运营账号':'添加运营账号',`<form id="account-form" data-id="${e(id)}"><div class="form-grid"><div class="form-field full"><label for="field-platform">所属平台</label><select class="input" id="field-platform" name="platform" ${id?'disabled':''}>${Object.entries(platforms).map(([key,label])=>`<option value="${key}" ${a.platform===key?'selected':''}>${label}</option>`).join('')}</select></div><div class="form-field full"><label for="field-name">账号名称 <span class="required">*</span></label><input class="input" id="field-name" name="name" value="${e(a.name)}" required maxlength="100"></div>${id?`<div class="form-field full"><label class="check-option"><input type="checkbox" name="active" ${a.active?'checked':''}>启用此账号</label><span class="hint">停用后保留历史数据，不再作为新文章的默认可选账号。</span></div>`:''}</div>${formEnd(id?'保存账号':'添加账号')}</form>`)}
function keyModal(){if(!state.accounts.some(a=>a.active)){toast('请先添加一个启用的运营账号。',true);return}openModal('创建 AI 接入凭证',`<form id="key-form"><div class="info-line">${icon('key',15)}<span>每个机器人建议使用独立凭证，方便确认修改来源、单独撤销授权。</span></div><div class="form-grid"><div class="form-field full"><label for="field-name">凭证名称 <span class="required">*</span></label><input class="input" name="name" id="field-name" placeholder="例如：Grok Bot · 日常回填" required maxlength="80"></div><fieldset class="form-field full" style="border:0;padding:0;margin:0"><legend class="field-label">允许访问的账号 <span class="required">*</span></legend><div class="checkboxes">${state.accounts.filter(a=>a.active).map(a=>`<label class="check-option"><input type="checkbox" name="account_ids" value="${e(a.id)}" ${state.account===a.id?'checked':''}>${e(accountLabel(a))}</label>`).join('')}</div><span class="hint">只勾选本次需要的账号；以后新增账号不会自动开放。</span></fieldset><fieldset class="form-field full" style="border:0;padding:0;margin:0"><legend class="field-label">允许的操作</legend><div class="checkboxes"><label class="check-option"><input type="checkbox" name="permissions" value="read" checked>读取文章与数据</label><label class="check-option"><input type="checkbox" name="permissions" value="write">新增与更新数据</label></div><span class="hint">凭证不能管理登录、账号、其他凭证和操作记录。</span></fieldset></div>${formEnd('创建凭证')}</form>`)}
function renderLogin(){renderVersion++;$('#app').innerHTML=`<main id="main" class="login-page"><section class="login-story"><div class="brand"><span class="brand-mark">${icon('fish',27)}</span><span><span class="brand-title">好多鱼图文</span><span class="brand-sub">CONTENT WORKSPACE</span></span></div><div class="login-copy"><div class="eyebrow">你的内容，持续生长</div><h1>把每一次发布，<br>变成看得见的积累。</h1><p>在一个工作空间，照看你的账号矩阵。<br>记录发布，与 AI 协作，从数据中找到方向。</p><div class="login-chips"><span>账号矩阵</span><span>发布记录</span><span>内容复盘</span></div></div><p class="login-foot">私有工作空间 · 仅你与授权的 AI 可访问</p></section><section class="login-form-side"><div class="login-form-wrap"><div class="eyebrow">WELCOME BACK</div><h2>回到你的工作空间</h2><p>使用网站账号登录好多鱼图文。</p><form id="login-form"><div class="form-field"><label for="username">账号</label><input class="input" id="username" name="username" autocomplete="username" required autofocus></div><div class="form-field"><label for="password">密码</label><input class="input" id="password" name="password" type="password" autocomplete="current-password" required></div><p class="form-message" role="alert"></p><button class="btn primary" type="submit">登录工作空间 ${icon('arrow',15)}</button></form><p class="login-note">经营数据不公开。AI 请通过独立授权凭证接入。</p></div></section></main>`}

document.addEventListener('click',async event=>{const target=event.target.closest('[data-action],[data-nav]');if(!target){if(event.target.classList.contains('modal-backdrop'))closeModal();if(event.target.classList.contains('shell')&&$('.shell').classList.contains('menu-open'))$('.shell').classList.remove('menu-open');return}if(target.dataset.nav){event.preventDefault();navigate(target.dataset.nav);return}const action=target.dataset.action,id=target.dataset.id;try{switch(action){case 'save-view':openModal('保存常用视图',`<form id="save-view-form">${field('name','视图名称 <span class="required">*</span>','text','','maxlength="80" required placeholder="例如：本周自动化发布"')}<p class="cell-sub" style="margin-top:12px">保存当前筛选、排序、分组及显示字段。账号切换保持独立，视图保存在此浏览器。</p>${formEnd('保存视图')}</form>`);break;case 'close-modal':closeModal();break;case 'menu':{const open=$('.shell').classList.toggle('menu-open');target.setAttribute('aria-expanded',String(open));break}case 'logout':await api('/auth/logout',{method:'POST'});state.me=null;renderLogin();break;case 'refresh':renderPage();break;case 'new-article':await articleModal();break;case 'edit-article':await articleModal(id);break;case 'article-detail':await articleDetail(id);break;case 'review-article':await reviewModal(id,target.dataset.kind||'latest');break;case 'new-review':await reviewModal();break;case 'review-tab':state.reviewTab=target.dataset.tab;renderPage();break;case 'new-account':accountModal();break;case 'edit-account':accountModal(id);break;case 'new-key':keyModal();break;case 'select-account':state.account=id;updateRoute();renderShell();break;case 'record-detail':{const row=state.reviewRecords.find(r=>r.id===id);if(row)openModal('数据记录详情',`${renderSnapshot(row)}<p class="cell-sub" style="margin-top:15px">${e(row.date?'统计日期：'+row.date:'数据截至：'+time(row.as_of))}${row.updated_at?' · 更新于 '+e(time(row.updated_at)):''}</p>`);break}case 'revoke-key':openModal('撤销 AI 凭证',`<p style="font-size:13px;line-height:1.9">撤销「${e(target.dataset.name)}」后，使用此凭证的 AI 将无法继续访问数据。已有记录会保留。</p><form id="revoke-form" data-id="${e(id)}">${formEnd('确认撤销')}</form>`);break;case 'copy-token':{const token=$('#created-token').textContent;try{await navigator.clipboard.writeText(token);toast('凭证已复制，请在安全位置保存。')}catch{const range=document.createRange();range.selectNodeContents($('#created-token'));const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);toast('已选中凭证，请手动复制。')}break}case 'reset-filters':state.filters={q:'',mode:'',from:'',to:'',sort:'published_at',order:'desc',group:''};renderPage();break}}catch(err){toast(err.message,true)}});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='saved-view'){const view=state.savedViews.find(v=>v.id===el.value);if(view){state.filters={...state.filters,...view.filters};state.columns=new Set(view.columns);renderPage()}}else if(el.id==='global-account'){state.account=el.value;updateRoute();renderShell()}else if(el.id==='trend-metric'){state.trendMetric=el.value;$('#page-content').innerHTML=renderDashboard(state.dashboard)}else if(el.closest('#article-filters')){state.filters[el.name]=el.value;renderPage()}else if(el.dataset.column){el.checked?state.columns.add(el.dataset.column):state.columns.delete(el.dataset.column);const table=$('#article-table');if(table&&state.articles.length)table.innerHTML=articleTable(state.articles)}else if(el.id==='review-account'){const select=$('#review-article');select.innerHTML='<option value="">账号总体（推荐）</option>'+state.articles.filter(a=>a.account_id===el.value).map(a=>`<option value="${e(a.id)}">${e(a.title)}</option>`).join('')}});
document.addEventListener('input',event=>{const el=event.target;if(el.name==='q'&&el.closest('#article-filters')){state.filters.q=el.value;clearTimeout(searchTimer);searchTimer=setTimeout(async()=>{const start=el.selectionStart;await renderPage();const next=$('#article-filters input[name=q]');if(next){next.focus();next.setSelectionRange(start,start)}},350)}});
document.addEventListener('keydown',event=>{if(!$('#overlay').firstChild)return;if(event.key==='Escape'){event.preventDefault();closeModal()}if(event.key==='Tab'){const nodes=$$('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]',$('#overlay')).filter(el=>el.getClientRects().length);if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}});
document.addEventListener('submit',async event=>{const form=event.target;if(!form.matches('#login-form,#article-form,#review-form,#account-form,#key-form,#password-form,#revoke-form,#article-filters,#save-view-form'))return;event.preventDefault();if(form.id==='article-filters')return;const button=$('button[type=submit]',form),message=$('.form-message',form),values=new FormData(form),data=Object.fromEntries(values);if(message)message.textContent='';if(button)button.disabled=true;try{switch(form.id){case 'save-view-form':{const saved={id:crypto.randomUUID(),name:data.name.trim(),filters:{...state.filters},columns:[...state.columns]};if(!saved.name)throw new Error('请填写视图名称。');state.savedViews=state.savedViews.filter(v=>v.name!==saved.name).concat(saved).slice(-20);storage.set('haoduoyu.views',JSON.stringify(state.savedViews));closeModal();toast('常用视图已保存在此浏览器。');await renderPage();break}case 'login-form':await api('/auth/login',{method:'POST',body:{username:data.username,password:data.password}});await init();break;case 'article-form':{const body={account_id:data.account_id,title:data.title.trim(),url:data.url.trim(),published_at:iso(data.published_at),started_at:iso(data.started_at),production_mode:data.production_mode,summary:data.summary,notes:data.notes,platform_article_id:data.platform_article_id?.trim()||''};if(!safeURL(body.url))throw new Error('文章链接请使用 http 或 https 地址。');if(body.started_at&&new Date(body.started_at)>new Date(body.published_at))throw new Error('选题开始时间不能晚于发布时间。');const id=form.dataset.id;if(id)body.version=Number(form.dataset.version);await api(id?`/articles/${encodeURIComponent(id)}`:'/articles',{method:id?'PUT':'POST',body});closeModal();toast(id?'发布记录已更新。':'发布记录已保存。');await renderPage();break}case 'review-form':{const m={};for(const key of Object.keys(metrics)){const value=data[`metric_${key}`];if(value!==''&&value!=null)m[key]=Number(value)}if(!Object.keys(m).length)throw new Error('请至少填写一个已取得的指标。');let body,path;if(form.dataset.type==='daily'){path='/daily-metrics';body={account_id:data.account_id,article_id:data.article_id||null,date:data.date,metrics:m,source:data.source.trim()}}else{path='/observations';body={article_id:data.article_id,kind:data.kind,as_of:iso(data.as_of),collected_at:iso(data.collected_at),metrics:m,source:data.source.trim(),note:data.note}}await api(path,{method:'POST',body});closeModal();toast('数据已保存，驾驶舱会同步更新。');await renderPage();break}case 'account-form':{const id=form.dataset.id;await api(id?`/accounts/${encodeURIComponent(id)}`:'/accounts',{method:id?'PUT':'POST',body:id?{name:data.name.trim(),active:values.has('active')}:{platform:data.platform,name:data.name.trim()}});state.accounts=(await api('/accounts')).sort((a,b)=>['toutiao','zhihu','wechat','other'].indexOf(a.platform)-['toutiao','zhihu','wechat','other'].indexOf(b.platform));closeModal();toast('运营账号已保存。');renderShell();break}case 'key-form':{const ids=values.getAll('account_ids'),permissions=values.getAll('permissions');if(!ids.length)throw new Error('请至少选择一个允许访问的账号。');if(!permissions.length)throw new Error('请至少选择一种操作权限。');const result=await api('/api-keys',{method:'POST',body:{name:data.name.trim(),account_ids:ids,permissions}});openModal('凭证已创建 · 请立即保存',`<div class="info-line amber">${icon('key',15)}<span>此凭证只显示一次，关闭后无法再次查看。请复制到你的 AI 安全凭证设置中，避免发送到公开聊天或文档。</span></div><pre class="token-box" id="created-token">${e(result.token)}</pre><div class="form-actions"><button class="btn" data-action="copy-token">${icon('copy',14)}复制凭证</button><button class="btn primary" data-action="close-modal">我已保存</button></div>`);await renderPage();break}case 'revoke-form':await api(`/api-keys/${encodeURIComponent(form.dataset.id)}`,{method:'DELETE'});closeModal();toast('凭证已撤销。');await renderPage();break;case 'password-form':if(data.newPassword!==data.confirmPassword)throw new Error('两次输入的新密码不一致。');await api('/auth/password',{method:'PUT',body:{currentPassword:data.currentPassword,newPassword:data.newPassword}});form.reset();toast('密码已更新，请使用新密码登录。');state.me=null;renderLogin();break}}catch(err){if(message&&message.isConnected)message.textContent=err.code==='VERSION_CONFLICT'?'这条记录已被其他人或 AI 更新。请关闭后重新打开，核对最新内容再保存。':err.message;else toast(err.message,true)}finally{if(button?.isConnected)button.disabled=false}});
window.addEventListener('popstate',()=>{const params=new URLSearchParams(location.search);state.page=nav.some(n=>n.id===params.get('page'))?params.get('page'):'dashboard';state.account=params.get('account')||'';if(state.me)renderShell()});
async function init(){try{try{const views=JSON.parse(storage.get('haoduoyu.views')||'[]');state.savedViews=Array.isArray(views)?views.filter(v=>typeof v?.id==='string'&&typeof v.name==='string'&&v.filters&&typeof v.filters==='object'&&Array.isArray(v.columns)).slice(-20):[]}catch{state.savedViews=[]}state.me=await api('/auth/me');state.accounts=(await api('/accounts')).sort((a,b)=>['toutiao','zhihu','wechat','other'].indexOf(a.platform)-['toutiao','zhihu','wechat','other'].indexOf(b.platform));const params=new URLSearchParams(location.search);state.page=nav.some(n=>n.id===params.get('page'))?params.get('page'):'dashboard';const candidate=params.has('account')?params.get('account'):storage.get('haoduoyu.account')||'';state.account=state.accounts.some(a=>a.id===candidate)?candidate:'';updateRoute();renderShell()}catch(err){if(err.status!==401){renderLogin();toast(err.message,true)}else renderLogin()}}
init();
